/** Independently authored ZeroSum alternative. Upstream is a visual reference only. */
import { setup, action, escapeText, type OriginalOptions, type OriginalHandle } from './runtime.ts';
export function mount(el: HTMLElement, opts: OriginalOptions = {}): OriginalHandle {
    const s = setup(el, "<div class=\"listen panel\"><div class=\"album art\"></div><span class=\"eyebrow\">Listening room \u00b7 UI demo</span><h2 class=\"track-title\">Soft horizon</h2><p class=\"muted\">Studio Session / Vol. 02</p><input type=\"range\" min=\"0\" max=\"180\" value=\"42\" aria-label=\"Playback position\"><div class=\"row between\"><small class=\"position\">0:42 / 3:00</small><div class=\"row\"><button data-action=\"previous\" aria-label=\"Previous track\">\u2190</button><button data-action=\"play\" aria-pressed=\"false\">Play</button><button data-action=\"next\" aria-label=\"Next track\">\u2192</button></div></div><p role=\"status\">Player interaction demo \u00b7 no audio source</p></div>", opts);
    let i = 0;
    s.on('click', e => { const a = action(e); if (a === 'play') {
        const b = e.target as HTMLElement, p = b.getAttribute('aria-pressed') !== 'true';
        b.setAttribute('aria-pressed', String(p));
        b.textContent = p ? 'Pause' : 'Play';
        s.status(p ? 'Playing state · UI demo, no audio source' : 'Paused state · UI demo');
    } if (a === 'next' || a === 'previous') {
        i = (i + (a === 'next' ? 1 : 2)) % 3;
        s.query('.track-title').textContent = ['Soft horizon', 'Night transit', 'Ocean glass'][i]!;
    } });
    s.on('input', e => { const n = Number((e.target as HTMLInputElement).value); s.query('.position').textContent = `${Math.floor(n / 60)}:${String(n % 60).padStart(2, '0')} / 3:00`; });
    return { destroy: s.destroy };
}

/** Independently authored by ZeroSum. No upstream component source is used. */
export interface OriginalOptions { theme?: 'light' | 'dark'; reducedMotion?: boolean }
export interface OriginalHandle { destroy(): void }
export function setup(el: HTMLElement, html: string, opts: OriginalOptions = {}) {
  const attributes = [...el.attributes].map(a => [a.name, a.value] as const);
  const children = [...el.childNodes];
  const abort = new AbortController();
  el.classList.add('mm-original');
  el.dataset.theme = opts.theme ?? 'dark';
  el.dataset.reducedMotion = String(opts.reducedMotion ?? false);
  el.innerHTML = html;
  function on(event: string, callback: (event: Event) => void) {
    el.addEventListener(event, callback, { signal: abort.signal });
  }
  function query<T extends Element = HTMLElement>(selector: string): T { return el.querySelector<T>(selector)!; }
  function status(text: string) { const node = el.querySelector('[role=status]'); if (node) node.textContent = text; }
  let destroyed = false;
  return { el, on, query, status, signal: abort.signal, get reducedMotion() { return opts.reducedMotion || el.ownerDocument.defaultView?.matchMedia?.('(prefers-reduced-motion: reduce)').matches || false; }, destroy() {
    if (destroyed) return;
    destroyed = true;
    el.querySelectorAll('dialog[open]').forEach(d => (d as HTMLDialogElement).close());
    abort.abort();
    el.replaceChildren(...children);
    for (const a of [...el.attributes]) el.removeAttribute(a.name);
    for (const [name, value] of attributes) el.setAttribute(name, value);
  } };
}
export function action(event: Event): string | undefined {
  return (event.target as Element).closest<HTMLElement>('[data-action]')?.dataset.action;
}
export function escapeText(value: string): string {
  return value.replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[c]!);
}

